function generateMap(canvasId) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    const CELL_SIZE = 10;
    const COLS = canvas.width / CELL_SIZE | 0;
    const ROWS = canvas.height / CELL_SIZE | 0;
    const map = new Uint8Array(COLS * ROWS); // 0 wall, 1 floor, 2 spawn, 3 weapon
    const rand = (min, max) => Math.random() * (max - min) + min;
    const randInt = (min, max) => Math.floor(rand(min, max + 1));

    // BSP room generation
    const MIN_ROOM_SIZE = 6;
    const MAX_ROOM_SIZE = 12;
    const rooms = [];

    function split(node, depth) {
        if (depth === 0 || (node.w <= MIN_ROOM_SIZE * 2 && node.h <= MIN_ROOM_SIZE * 2)) {
            const w = randInt(MIN_ROOM_SIZE, Math.min(node.w - 2, MAX_ROOM_SIZE));
            const h = randInt(MIN_ROOM_SIZE, Math.min(node.h - 2, MAX_ROOM_SIZE));
            const x = randInt(node.x + 1, node.x + node.w - w - 1);
            const y = randInt(node.y + 1, node.y + node.h - h - 1);
            rooms.push({x, y, w, h});
            return;
        }
        const horizontal = node.w < node.h ? true : node.w > node.h ? false : Math.random() < 0.5;
        if (horizontal) {
            const splitY = randInt(node.y + MIN_ROOM_SIZE, node.y + node.h - MIN_ROOM_SIZE);
            split({x: node.x, y: node.y, w: node.w, h: splitY - node.y}, depth - 1);
            split({x: node.x, y: splitY, w: node.w, h: node.y + node.h - splitY}, depth - 1);
        } else {
            const splitX = randInt(node.x + MIN_ROOM_SIZE, node.x + node.w - MIN_ROOM_SIZE);
            split({x: node.x, y: node.y, w: splitX - node.x, h: node.h}, depth - 1);
            split({x: splitX, y: node.y, w: node.x + node.w - splitX, h: node.h}, depth - 1);
        }
    }

    split({x: 0, y: 0, w: COLS, h: ROWS}, 4);

    // Carve rooms
    rooms.forEach(r => {
        for (let y = r.y; y < r.y + r.h; y++) {
            for (let x = r.x; x < r.x + r.w; x++) {
                map[y * COLS + x] = 1;
            }
        }
    });

    // Connect rooms via corridors using simple MST on room centers
    const centers = rooms.map(r => ({x: Math.floor(r.x + r.w / 2), y: Math.floor(r.y + r.h / 2)}));
    const edges = [];
    for (let i = 0; i < centers.length; i++) {
        for (let j = i + 1; j < centers.length; j++) {
            const a = centers[i], b = centers[j];
            const d = Math.abs(a.x - b.x) + Math.abs(a.y - b.y);
            edges.push({i, j, d});
        }
    }
    edges.sort((a, b) => a.d - b.d);

    const parent = new Uint16Array(centers.length);
    for (let i = 0; i < parent.length; i++) parent[i] = i;
    const find = i => (parent[i] === i ? i : (parent[i] = find(parent[i])));
    const union = (a, b) => {
        const ra = find(a), rb = find(b);
        if (ra !== rb) parent[rb] = ra;
    };

    const corridors = [];
    for (let e of edges) {
        if (find(e.i) !== find(e.j)) {
            union(e.i, e.j);
            corridors.push([centers[e.i], centers[e.j]]);
        }
    }

    const carve = (x0, y0, x1, y1) => {
        let x = x0, y = y0;
        while (x !== x1) {
            map[y * COLS + x] = 1;
            x += x < x1 ? 1 : -1;
        }
        while (y !== y1) {
            map[y * COLS + x] = 1;
            y += y < y1 ? 1 : -1;
        }
        map[y * COLS + x] = 1;
    };
    corridors.forEach(c => {
        carve(c[0].x, c[0].y, c[1].x, c[0].y);
        carve(c[1].x, c[0].y, c[1].x, c[1].y);
    });

    // Flood fill from first room center to ensure reachability
    const reachable = new Uint8Array(COLS * ROWS);
    const stack = [centers[0].y * COLS + centers[0].x];
    reachable[stack[0]] = 1;
    while (stack.length) {
        const idx = stack.pop();
        const x = idx % COLS, y = (idx / COLS) | 0;
        const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
        for (let d of dirs) {
            const nx = x + d[0], ny = y + d[1];
            if (nx < 0 || ny < 0 || nx >= COLS || ny >= ROWS) continue;
            const nIdx = ny * COLS + nx;
            if (!reachable[nIdx] && map[nIdx] === 1) {
                reachable[nIdx] = 1;
                stack.push(nIdx);
            }
        }
    }
    // Connect any unreachable floor tiles
    for (let i = 0; i < map.length; i++) {
        if (map[i] === 1 && !reachable[i]) {
            const x = i % COLS, y = (i / COLS) | 0;
            // carve a simple path to nearest reachable tile
            let tx = x, ty = y;
            while (!reachable[ty * COLS + tx]) {
                const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
                let best = null, bestDist = Infinity;
                for (let d of dirs) {
                    const nx = tx + d[0], ny = ty + d[1];
                    if (nx < 0 || ny < 0 || nx >= COLS || ny >= ROWS) continue;
                    const dist = Math.abs(nx - centers[0].x) + Math.abs(ny - centers[0].y);
                    if (dist < bestDist) {bestDist = dist; best = [nx, ny];}
                }
                tx = best[0]; ty = best[1];
                map[ty * COLS + tx] = 1;
                reachable[ty * COLS + tx] = 1;
            }
        }
    }

    // Place spawn points (green) far apart
    const spawnPoints = [];
    const sortedCenters = centers.slice().sort((a,b)=>Math.hypot(a.x-b.x,a.y-b.y));
    spawnPoints.push(sortedCenters[0]);
    let far = sortedCenters[sortedCenters.length-1];
    spawnPoints.push(far);
    spawnPoints.forEach(p=> map[p.y * COLS + p.x] = 2);

    // Place weapon pickups (red)
    const weaponCount = Math.max(3, Math.floor(rooms.length / 3));
    let placed = 0;
    while (placed < weaponCount) {
        const r = rooms[randInt(0, rooms.length-1)];
        const wx = randInt(r.x, r.x + r.w -1);
        const wy = randInt(r.y, r.y + r.h -1);
        const idx = wy * COLS + wx;
        if (map[idx] === 1) {
            map[idx] = 3;
            placed++;
        }
    }

    // Draw map
    ctx.clearRect(0,0,canvas.width,canvas.height);
    for (let y = 0; y < ROWS; y++) {
        for (let x = 0; x < COLS; x++) {
            const val = map[y * COLS + x];
            if (val === 0) {
                ctx.fillStyle = '#000';
            } else if (val === 1) {
                ctx.fillStyle = '#777';
            } else if (val === 2) {
                ctx.fillStyle = '#0f0';
            } else if (val === 3) {
                ctx.fillStyle = '#f00';
            }
            ctx.fillRect(x*CELL_SIZE, y*CELL_SIZE, CELL_SIZE, CELL_SIZE);
        }
    }

    // Legend
    const legend = document.getElementById('map-legend');
    if (!legend) {
        const lg = document.createElement('div');
        lg.id = 'map-legend';
        lg.style.position = 'absolute';
        lg.style.top = canvas.offsetTop + 'px';
        lg.style.left = (canvas.offsetLeft + canvas.width + 10) + 'px';
        lg.style.fontFamily = 'sans-serif';
        lg.innerHTML = `
            <div><span style="display:inline-block;width:12px;height:12px;background:#000;margin-right:4px;"></span>Wall</div>
            <div><span style="display:inline-block;width:12px;height:12px;background:#777;margin-right:4px;"></span>Floor</div>
            <div><span style="display:inline-block;width:12px;height:12px;background:#0f0;margin-right:4px;"></span>Spawn</div>
            <div><span style="display:inline-block;width:12px;height:12px;background:#f00;margin-right:4px;"></span>Weapon</div>
        `;
        document.body.appendChild(lg);
    }

    // Button
    const btnId = 'gen-map-btn';
    let btn = document.getElementById(btnId);
    if (!btn) {
        btn = document.createElement('button');
        btn.id = btnId;
        btn.textContent = 'Generate New Map';
        btn.style.position = 'absolute';
        btn.style.top = (canvas.offsetTop + canvas.height + 10) + 'px';
        btn.style.left = canvas.offsetLeft + 'px';
        document.body.appendChild(btn);
        btn.addEventListener('click', () => generateMap(canvasId));
    }
}
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => generateMap('mapCanvas'));
} else {
    generateMap('mapCanvas');
}
